#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "mvt.h"

/* Include the Exo-generated kernel header. */
#include "generated/mvt/mvt.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x1[i]  = (DATA_TYPE) (i % n)      / n;
      x2[i]  = (DATA_TYPE) ((i + 1) % n) / n;
      y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
      y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i * j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x1,N,n),
		 DATA_TYPE POLYBENCH_1D(x2,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x1");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tile size along the inner j-dimension for better cache reuse.
# The tail of the loop is handled safely by divide_loop with guards.
J_TILE = 64


@proc
def kernel_mvt(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # First matrix–vector product:
    #   x1[i] += sum_j A[i, j] * y_1[j]
    for i in seq(0, n):
        for j in seq(0, n):
            x1[i] += A[i, j] * y_1[j]

    # Second matrix–vector product:
    #   x2[i] += sum_j A[j, i] * y_2[j]
    for i in seq(0, n):
        for j in seq(0, n):
            x2[i] += A[j, i] * y_2[j]


# ---------------------------------------------------------------------------
# Scheduling: improve data locality & parallelism while preserving semantics.
# ---------------------------------------------------------------------------

# 1) Optimize the first matvec: x1 += A * y_1
#
# - Access pattern is already row-major in A (A[i, j]) and unit-stride in y_1[j].
# - We:
#   * block the inner j-loop to improve temporal locality of y_1 and A's rows,
#   * parallelize the outer i-loop because each i updates a disjoint x1[i].

# Get the two top-level i-loops (one for each matvec).
i_loops = kernel_mvt.find_all("for i in _:_")
mvt1_i = i_loops[0]   # first matvec's i-loop

# Tile the inner j-loop of the first matvec with factor J_TILE.
# This rewrites:
#   for j in seq(0, n): ...
# into a j_outer / j_inner structure with guards for the tail.
j1 = mvt1_i.body().find_loop("j")
kernel_mvt = divide_loop(kernel_mvt, j1, J_TILE, ("j_outer", "j_inner"), tail="guard")

# Parallelize the outer i-loop of the first matvec.
# Different i-iterations write to distinct x1[i] and only read A and y_1,
# so the loop is embarrassingly parallel.
mvt1_i = kernel_mvt.find_loop("i #0")
kernel_mvt = parallelize_loop(kernel_mvt, mvt1_i)


