#
# Original structure:
#   for i in seq(0, n):
#       for j in seq(0, n):
#           x2[i] += A[j, i] * y_2[j]
#
# This walks A by columns (A[j, i]) on row-major storage. We interchange
# the loops so that the inner loop walks across rows of A:
#
#   for j in seq(0, n):
#       for i in seq(0, n):
#           x2[i] += A[j, i] * y_2[j]
#
# For each i, the set of (j, A[j, i] * y_2[j]) terms is unchanged; only
# the accumulation order changes, which is mathematically equivalent.

# Re-fetch i-loops after the previous transformation.
i_loops = kernel_mvt.find_all("for i in _:_")
mvt2_i = i_loops[1]   # second matvec's i-loop

# Interchange the second matvec's i-outer and its nested j-inner loops.
kernel_mvt = reorder_loops(kernel_mvt, mvt2_i)


# 3) Clean up algebraically-simplifiable constructs.
kernel_mvt = simplify(kernel_mvt)
