from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Optimized Exo kernel for MVT:
#   x1[i] += sum_j A[i, j] * y_1[j]
#   x2[i] += sum_j A[j, i] * y_2[j]
#
# We improve:
#   - Data locality for the second pass by traversing A row-major.
#   - Register usage by keeping x1[i] in a scalar accumulator.
#   - Parallelism by parallelizing independent loops with OpenMP.

@proc
def kernel_mvt(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    assert n >= 0

    # First matrix-vector multiply: x1 += A * y_1
    # Use a scalar accumulator so x1[i] stays in a register across the inner loop.
    for i in seq(0, n):
        acc1: DATA_TYPE
        acc1 = x1[i]
        for j in seq(0, n):
            acc1 += A[i, j] * y_1[j]
        x1[i] = acc1

    # Second matrix-vector multiply: x2 += A^T * y_2
    # Original semantics:
    #   for i in 0..n-1:
    #     for j in 0..n-1:
    #       x2[i] = x2[i] + A[j, i] * y_2[j]
    #
    # This accesses A in column-major order (A[j, i]) on row-major storage.
    # We algebraically reorder the reduction:
    #   x2[i] = x2[i] + sum_j A[j, i] * y_2[j]
    # is equivalent to:
    #   for j in 0..n-1:
    #     tmp = y_2[j]
    #     for i in 0..n-1:
    #       x2[i] = x2[i] + A[j, i] * tmp
    #
    # This keeps A[j, :] row-contiguous and hoists y_2[j] into a scalar.
    for j in seq(0, n):
        tmp_y2: DATA_TYPE
        tmp_y2 = y_2[j]
        for i in seq(0, n):
            x2[i] = x2[i] + A[j, i] * tmp_y2

# -----------------------------
# Scheduling for performance
# -----------------------------
# We now apply Exo scheduling primitives to exploit multicore parallelism.
# The resulting C code will typically lower to OpenMP `#pragma omp parallel for`
# on the chosen loops.

kernel_mvt_sched = kernel_mvt

# 1) Parallelize the outer i-loop of the first phase:
#    - Each iteration touches a distinct x1[i] and a distinct row A[i, :].
#    - y_1 and A are read-only, so there are no cross-iteration dependences.
i_outer = kernel_mvt_sched.find_loop("i")
kernel_mvt_sched = parallelize_loop(kernel_mvt_sched, i_outer)

# 2) Parallelize the inner i-loop of the second phase:
#    - After the algebraic rewrite, for each fixed j we have:
#        for i: x2[i] += A[j, i] * tmp_y2
#    - Different iterations of this i-loop write to distinct x2[i],
#      so it is safe to parallelize.
i_inner = kernel_mvt_sched.find_loop("i #1")
kernel_mvt_sched = parallelize_loop(kernel_mvt_sched, i_inner)

# Rebind the public kernel name to the scheduled version.
kernel_mvt = kernel_mvt_sched
